import { REPERTOIRE_ARRANGEMENTS } from './repertoire.js';
import { interactionChoice, activityQuote } from './interaction-ui-v40.js';
import { actionCostDetails } from './action-costs.js';

// This is the player's manuscript book, not words automatically told to an NPC.
export function renderRepertoire(s,actions,ui,{surface='book'}={}) {
  if(s.age<18)return '';
  const {e}=ui,r=s.repertoire,offers=actions.filter(a=>a.id.startsWith('repertoire_'));
  const controls=rows=>rows.map(a=>interactionChoice(ui,{label:a.label,op:'activity',id:a.id,description:a.description,meta:activityQuote(a,s),costDetails:actionCostDetails(s,a),disabledReason:a.disabledReason})).join('');
  const forPiece=id=>offers.filter(a=>a.id.includes('_'+id+'_')||a.id==='repertoire_delete_'+id);
  const receiptRows=(r?.performances||[]).map(p=>`<article class="remembered-entry"><h4>${e(p.piece.title)} · Revision ${p.piece.revision}</h4><p>${e(p.venue.name)} · Day ${p.performedDay} · ${e(p.listener.name)} · ${e(p.reception)} reception</p><p class="small-copy">${p.permission==='once'?'Public rendition only; no manuscript copy permitted.':'This performed version permitted a manuscript copy.'}</p></article>`).join('');
  const pending=r?.project,project=pending?`<p>${e(pending.piece.title)} · Revision ${pending.piece.revision} · ${pending.completedDays}/${pending.totalDays} attended days. The saved ${pending.arrangement==='solo'?'solo':'refrain'} and public permission remain unchanged.</p>${controls(offers.filter(a=>['repertoire_continue','repertoire_cancel','repertoire_withdraw'].includes(a.id)))}`:'';
  const pieces=(r?.pieces||[]).map(p=>`<article class="repertoire-piece"><h4>${e(p.title)} · Revision ${p.revision}</h4><p class="small-copy">${p.privacy==='private'?'Private manuscript':'Public copies explicitly allowed'} · ${p.rehearsal?`${e(REPERTOIRE_ARRANGEMENTS.find(a=>a.id===p.rehearsal.arrangement).name)} rehearsed on day ${p.rehearsal.completedDay}`:'This revision is unprepared'}</p><details data-disclosure="repertoire:verse:${e(p.id)}"><summary>Read your manuscript${p.privacy==='private'?' · private':''}</summary>${p.verse.split('\n').map(line=>`<p>${e(line)}</p>`).join('')}<p class="small-copy">Original fiction, not a quotation or recovered testimony. Words: ${e(p.credits.map(c=>c.name).join(', '))}. Composed at ${e(s.world.locations.find(l=>l.id===p.source.locationId)?.name||p.source.locationId)} on day ${p.source.day}.</p></details><div class="interaction-options">${controls(forPiece(p.id))}</div></article>`).join('');
  const circuit=r?.circuit?`<section class="repertoire-circuit"><h4>Three actual Taverns</h4><p>${r.circuit.completedDay!==null?'All three recitals recorded.':r.circuit.withdrawnDay!==null?'Circuit withdrawn. Earlier heard versions remain.':'An optional, unpaid circuit. Travel is separate; fixed targets never silently change.'}</p><ul>${r.circuit.targets.map(t=>`<li>${e(t.name)} · ${r.circuit.stops.some(p=>p.locationId===t.locationId)?'Performed':'Not performed'}</li>`).join('')}</ul>${controls(offers.filter(a=>a.id==='repertoire_withdraw'))}</section>`:controls(offers.filter(a=>a.id==='repertoire_accept'));
  const content=`<h3 id="repertoire-heading" tabindex="-1">Songs &amp; Stories</h3><p class="small-copy">Your manuscript book. Reading a private draft here does not tell it to anyone. Each recital separately asks for a public rendition once or an explicitly permitted manuscript copy. Unpaid art grants no career days, wages, commissions or skills.</p>${project||`${pieces}<div class="interaction-options">${controls(offers.filter(a=>a.id.startsWith('repertoire_create_')))}</div>${circuit}`}${controls(offers.filter(a=>a.id.startsWith('repertoire_recall_')))}${receiptRows?`<details data-disclosure="repertoire:heard"><summary>Versions actually heard (${r.performances.length})</summary>${receiptRows}</details>`:''}`;
  return surface==='inn'?`<section class="repertoire-book" aria-label="Your manuscript book">${content}</section>`:`<details class="repertoire-book" data-disclosure="repertoire:book"><summary>Songs &amp; Stories · ${r?.pieces.length||0}/3 pieces${pending?' · commitment in progress':''}</summary>${content}</details>`;
}
